const std::string &MagmaSubscriptions::getValueOfId() const noexcept
{
    static const std::string defaultValue = std::string();
    if(id_)
        return *id_;
    return defaultValue;
}
const std::shared_ptr<std::string> &MagmaSubscriptions::getId() const noexcept
{
    return id_;
}
void MagmaSubscriptions::setId(const std::string &pId) noexcept
{
    id_ = std::make_shared<std::string>(pId);
    dirtyFlag_[0] = true;
}
void MagmaSubscriptions::setId(std::string &&pId) noexcept
{
    id_ = std::make_shared<std::string>(std::move(pId));
    dirtyFlag_[0] = true;
}
const typename MagmaSubscriptions::PrimaryKeyType & MagmaSubscriptions::getPrimaryKey() const
{
    assert(id_);
    return *id_;
}

