MagmaSubscribers MagmaSubscriptions::getMagmaSubscribers(const DbClientPtr &clientPtr) const {
    static const std::string sql = "select * from magma_subscribers where id = $1";
    Result r(nullptr);
    {
        auto binder = *clientPtr << sql;
        binder << *subscriberId_ << Mode::Blocking >>
            [&r](const Result &result) { r = result; };
        binder.exec();
    }
    if (r.size() == 0)
    {
        throw UnexpectedRows("0 rows found");
    }
    else if (r.size() > 1)
    {
        throw UnexpectedRows("Found more than one row");
    }
    return MagmaSubscribers(r[0]);
}

